def process_stock_splits(price_df, split_events):
    adjusted_data = pd.DataFrame({'date': [price_df.index[0]], 'price': [price_df.iloc[0]]})
    for i in range(1, len(price_df)):
        date = price_df.index[i]
        price = price_df.iloc[i]
        if date in split_events:
            price = price / split_events[date]
        adjusted_data = adjusted_data.append({'date': date, 'price': price}, ignore_index=True)
    prices_arr = np.array(adjusted_data['price'].values, copy=False)
    return pd.DataFrame({'adj_close': prices_arr}, index=adjusted_data['date'])

