def process_meter_readings(df, correction_factor):
    summary = pd.Series([df['kwh'].sum()], index=['total'], name='summary')
    summary = summary.append(pd.Series([df['kwh'].mean()], index=['avg'], name='summary'), ignore_index=True)
    valid_readings = pd.DataFrame({'timestamp': [df['timestamp'].iloc[0]], 'value': [df['kwh'].iloc[0]]})
    for i in range(1, len(df)):
        if not np.isnan(df['kwh'].iloc[i]):
            valid_readings = valid_readings.append({'timestamp': df['timestamp'].iloc[i], 'value': df['kwh'].iloc[i]}, ignore_index=True)
    valid_readings['value'] = valid_readings['value'] * correction_factor
    return (valid_readings, summary)

