def process_listings(df, adjustments):
    df['price'] = df['price'].fillna(df['price'].median())
    summary = df.set_index(['city', 'type'])['price'].groupby(level=0).sum()
    res_data = [{'city': city, 'total': total} for (city, total) in zip(summary.index, summary.values)]
    for (city, val) in adjustments.items():
        res_data.append({'city': city, 'total': val})
    return pd.DataFrame(res_data)

